// Differential test: for every scenario in
// test/fixtures/differential-cases.json (generated by the real, unchanged
// Python engine via engine/differential/generate_cases.py), assert the
// TypeScript port (src/engine/) produces an identical Plan, field for
// field, except for fields that are inherently nondeterministic/
// language-specific (nonce, instance, time_utc, elapsed_ms,
// states_visited) -- generate_cases.py already strips those from the
// expected side, and this file strips them identically from the actual
// side before comparing.
//
// Cases: the known fixed scenarios from every prior phase of this project
// (default, both single-appliance repairs, the tied-repair determinism
// case, the demo sequence, all-zero, all-max, extreme capacity,
// forced-compromise-tier, power-conflict) plus 150 scenarios randomized
// under a fixed seed across usable_wh, max_w, and every appliance's
// required_hours; plus (Phase B) 7 hand-picked and 60 randomized scenarios
// that also vary the household's own essentials (critical_ids) selection
// -- see engine/differential/generate_cases.py's
// randomized_critical_ids_cases(). A case with no `critical_ids` field
// omits the parameter entirely on both sides, exercising the pre-Phase-B
// default-essentials call shape exactly as before.
import differentialCases from './fixtures/differential-cases.json';
import {buildPlan, validateRequest} from '../src/engine/plan';

type Case = {
  name: string;
  input: {
    usable_wh: number;
    max_w: number;
    appliances: Array<{id: string; required_hours: number}>;
    critical_ids?: string[];
  };
  expected: unknown;
};

function stripNondeterministic(value: unknown): unknown {
  const drop = new Set(['nonce', 'instance', 'time_utc', 'elapsed_ms', 'states_visited']);
  if (Array.isArray(value)) {
    return value.map(stripNondeterministic);
  }
  if (value !== null && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (!drop.has(k)) {
        out[k] = stripNondeterministic(v);
      }
    }
    return out;
  }
  return value;
}

describe('TypeScript engine vs Python engine (differential)', () => {
  const allCases = differentialCases.cases as Case[];

  it('loaded a substantial, non-trivial case set', () => {
    expect(allCases.length).toBeGreaterThan(150);
  });

  it.each(allCases.map(c => [c.name, c] as const))('%s', (_name, c) => {
    const {usableWh, maxW, overrides, criticalIds} = validateRequest(
      c.input.usable_wh,
      c.input.max_w,
      c.input.appliances,
      c.input.critical_ids,
    );
    const actual = stripNondeterministic(buildPlan(usableWh, maxW, overrides, criticalIds));
    expect(actual).toEqual(c.expected);
  });
});
